function hasKhmer(text) {
  for (let i = 0; i < text.length; i++) {
    const c = text.charCodeAt(i);
    if (c >= 0x1780 && c <= 0x17ff) return true;
  }
  return false;
}

let RE = null;
let RE_TOTAL = 0;

function ensureRegex() {
  if (RE && RE_TOTAL === Object.keys(KM_DICT).length) return RE;
  const keys = Object.keys(KM_DICT)
    .filter((k) => k.length >= 2)
    .sort((a, b) => b.length - a.length)
    .map((k) => k.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  RE_TOTAL = Object.keys(KM_DICT).length;
  RE = new RegExp("(?<![A-Za-z])(?:" + keys.join("|") + ")(?![A-Za-z])", "g");
  return RE;
}

// Translate a single English string to Khmer (substring-aware).
// Idempotent: text that already contains Khmer is returned unchanged.
export function translate(text) {
  if (typeof text !== "string" || text.length < 2) return text;
  if (hasKhmer(text)) return text;
  return text.replace(ensureRegex(), (m) => KM_DICT[m] || m);
}
